UPDATE `ACCOUNT`
SET INSTITUTION_NAME = #{institutionName},
    ACCOUNT_NAME = #{accountName},
    ACCOUNT_TYPE = #{accountType},
    ACCOUNT_NUMBER_MASKED = #{accountNumberMasked},
    BALANCE = #{balance},
    IS_ACTIVE = #{isActive},
    SYNCED_AT = #{syncedAt}
WHERE USER_ID = #{userId}
  AND EXTERNAL_ACCOUNT_ID = #{externalAccountId}
